#include <iostream>
#include <memory>

class Resource {
public:
    Resource() { std::cout << "Resource acquired" << std::endl; }
    ~Resource() { std::cout << "Resource destroyed" << std::endl; }
    void doSomething() { std::cout << "Doing something with resource" << std::endl; }
};

int main() {
    {
        auto ptr = std::make_unique<Resource>(); // unique_ptr manages Resource
        ptr->doSomething();
    } // Resource is automatically destroyed here when unique_ptr goes out of scope

    std::shared_ptr<Resource> sharedPtr1 = std::make_shared<Resource>(); // shared ownership
    {
        std::shared_ptr<Resource> sharedPtr2 = sharedPtr1; // shared ownership
        sharedPtr2->doSomething();
        std::cout << "Shared pointers count: " << sharedPtr1.use_count() << std::endl;
    } // sharedPtr2 destroyed, but Resource remains because sharedPtr1 still owns it
    std::cout << "Shared pointers count after inner scope: " << sharedPtr1.use_count() << std::endl;
    // weak_ptr does not affect resource lifetime
    std::weak_ptr<Resource> weakPtr = sharedPtr1;
    if (auto sp = weakPtr.lock()) {
        sp->doSomething();
    }
    return 0;
}
